require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');
if(request_method('POST')){Csrf::verify();$id=(int)($_POST['user_id']??0);$status=$_POST['eligibility_status']??'';if(in_array($status,['pending','eligible','ineligible'],true)){db()->prepare('UPDATE donor_profiles SET eligibility_status=?,eligibility_verified_at=CASE WHEN ?=\'eligible\' THEN NOW() ELSE NULL END WHERE user_id=?')->execute([$status,$status,$id]);audit('donor_eligibility_updated','user',$id,['status'=>$status]);flash('success','Donor eligibility updated.');}redirect('admin/donors.php');}
$rows=db()->query("SELECT u.id,u.full_name,u.email,u.phone,u.status,u.email_verified_at,u.phone_verified_at,dp.* FROM users u JOIN donor_profiles dp ON dp.user_id=u.id ORDER BY u.created_at DESC LIMIT 300")->fetchAll();$pageTitle='Manage Donors';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>Donor eligibility records</h1><p class="page-note">This prototype status represents administrative verification only. Medical eligibility is still decided by healthcare staff at the time of donation.</p></div></div><?=admin_nav()?><div class="table-wrap"><table class="table"><thead><tr><th>Donor</th><th>Blood</th><th>District</th><th>Verification</th><th>Availability / Consent</th><th>Eligibility</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No donors registered.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><br><span class="small"><?=e($r['email'])?></span></td><td><?=e($r['blood_group'])?></td><td><?=e($r['district'])?></td><td>Email: <?=$r['email_verified_at']?'✓':'—'?><br>Phone: <?=$r['phone_verified_at']?'✓':'—'?></td><td><?=e($r['availability'])?><br><span class="small">Consent: <?=e($r['consent_status'])?></span></td><td><span class="badge <?=$r['eligibility_status']==='eligible'?'green':($r['eligibility_status']==='ineligible'?'red':'amber')?>"><?=e($r['eligibility_status'])?></span></td><td><form method="post" class="mini-actions"><?=Csrf::field()?><input type="hidden" name="user_id" value="<?=e((string)$r['id'])?>"><select name="eligibility_status"><option value="pending" <?=$r['eligibility_status']==='pending'?'selected':''?>>Pending</option><option value="eligible" <?=$r['eligibility_status']==='eligible'?'selected':''?>>Eligible</option><option value="ineligible" <?=$r['eligibility_status']==='ineligible'?'selected':''?>>Ineligible</option></select><button class="btn btn-sm">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section>
